-- 부트 것을 하나 연다

$ AC=$(find ~/.gradle/caches -name 'spring-boot-autoconfigure-3.3.2.jar' | head -1)
$ unzip -p "$AC" org/springframework/boot/autoconfigure/web/servlet/\
ServletWebServerFactoryAutoConfiguration.class > /tmp/s.class
$ javap -v /tmp/s.class | grep -A2 'ConditionalOnClass' | head -3
  1: #33(#34=[c#35]): CONDITIONAL_ON_CLASS
     jakarta.servlet.ServletRequest

// 소스로는 이렇다
@AutoConfiguration
@ConditionalOnClass(ServletRequest.class)
@ConditionalOnWebApplication(type = Type.SERVLET)
public class ServletWebServerFactoryAutoConfiguration { ... }

--   5.5절에서 본 그 조건이다


-- 있을 때

dependencies {
    implementation 'org.springframework.boot:spring-boot-starter-web'
}

$ ./gradlew bootRun --args='--debug' 2>&1 \
    | grep -A2 'ServletWebServerFactoryAutoConfiguration matched' | head -3
   ServletWebServerFactoryAutoConfiguration matched:
      - @ConditionalOnClass found required class 'jakarta.servlet.ServletRequest'

$ ./gradlew bootRun 2>&1 | grep 'Tomcat started'
INFO ... : Tomcat started on port 8080 (http) with context path '/'


-- 없을 때

dependencies {
    implementation('org.springframework.boot:spring-boot-starter-web') {
        exclude group: 'org.springframework.boot', module: 'spring-boot-starter-tomcat'
    }
}

$ ./gradlew bootRun --args='--debug' 2>&1 \
    | grep -A3 'ServletWebServerFactoryAutoConfiguration' | head -4
   ServletWebServerFactoryAutoConfiguration:
      Did not match:
         - @ConditionalOnClass did not find required class
           'jakarta.servlet.ServletRequest'

$ curl -s -o /dev/null -w '%{http_code}\n' localhost:8080/hello
000

--   5.5절의 그 000 이 여기서 결정된다


-- 내가 하나 만든다

package study.lib;

@AutoConfiguration
@ConditionalOnClass(name = "com.fasterxml.jackson.databind.ObjectMapper")
public class PrettyAutoConfiguration {
    @Bean
    public String prettyMode() { return "켜짐"; }
}

// META-INF/spring/...AutoConfiguration.imports
study.lib.PrettyAutoConfiguration

$ ./gradlew bootRun --args='--debug' 2>&1 \
    | grep -A2 'PrettyAutoConfiguration matched' | head -3
   PrettyAutoConfiguration matched:
      - @ConditionalOnClass found required class
        'com.fasterxml.jackson.databind.ObjectMapper'

$ curl -s 'localhost:8080/beans/one?name=prettyMode'
켜짐


-- 잭슨을 뺀다

implementation('org.springframework.boot:spring-boot-starter-web') {
    exclude group: 'com.fasterxml.jackson.core', module: 'jackson-databind'
}

$ ./gradlew dependencies --configuration runtimeClasspath | grep -c jackson-databind
0

$ ./gradlew bootRun --args='--debug' 2>&1 \
    | grep -A3 'PrettyAutoConfiguration' | head -4
   PrettyAutoConfiguration:
      Did not match:
         - @ConditionalOnClass did not find required class
           'com.fasterxml.jackson.databind.ObjectMapper'

$ curl -s -o /dev/null -w '%{http_code}\n' \
    'localhost:8080/beans/one?name=prettyMode'
404

$ ./gradlew bootRun 2>&1 | grep -ci 'error\|warn'
0

--   JAR 하나가 스위치였다
--   경고는 여전히 없다


-- 타입으로 적어도 된다

@ConditionalOnClass(ObjectMapper.class)
public class PrettyAutoConfiguration { ... }

$ ./gradlew compileJava -q && echo 'compile OK'
compile OK

// 그런데 컴파일에는 있어야 한다
$ ./gradlew dependencies --configuration compileClasspath | grep -c jackson-databind
1
$ ./gradlew dependencies --configuration runtimeClasspath | grep -c jackson-databind
0

$ ./gradlew bootRun --args='--debug' 2>&1 | grep -c 'PrettyAutoConfiguration'
1
$ ./gradlew bootRun 2>&1 | grep -c 'Started BootApplication'
1

--   런타임에 없는데도 기동이 된다
--   6.3절에서 타입 직접 참조는 깨졌었다


-- 왜 안 터지나

$ javap -v build/classes/java/main/study/lib/PrettyAutoConfiguration.class \
    | grep -A2 'RuntimeVisibleAnnotations'
RuntimeVisibleAnnotations:
  0: #18(): AUTO_CONFIGURATION
  1: #19(#20=[c#21]): CONDITIONAL_ON_CLASS

$ javap -v build/classes/java/main/study/lib/PrettyAutoConfiguration.class \
    | grep -E '#21 = '
  #21 = Utf8   Lcom/fasterxml/jackson/databind/ObjectMapper;

--   상수 풀에 이름 문자열로만 들어 있다
--   읽는 쪽이 로딩을 안 하고 이름만 본다


-- 내 구성 클래스에 붙이면 다르다

package study.boot;   // 스캔되는 자리

@Configuration
@ConditionalOnClass(ObjectMapper.class)
public class MyPretty {
    @Bean public String myPretty() { return "내 것"; }
}

$ ./gradlew bootRun 2>&1 | head -4
Exception in thread "main" java.lang.IllegalStateException:
  Failed to introspect annotated methods on class study.boot.MyPretty
Caused by: java.lang.NoClassDefFoundError:
  com/fasterxml/jackson/databind/ObjectMapper

--   스캔으로 잡히면 클래스를 로딩한다
--   자동 구성은 다른 방식으로 읽힌다


-- 메서드 반환 타입도 위험하다

@AutoConfiguration
@ConditionalOnClass(name = "com.fasterxml.jackson.databind.ObjectMapper")
public class PrettyAutoConfiguration {
    @Bean
    public ObjectMapper prettyMapper() { return new ObjectMapper(); }
}

// 잭슨이 있으면
$ ./gradlew bootRun 2>&1 | grep -c 'Started BootApplication'
1

// 잭슨을 빼면
$ ./gradlew bootRun 2>&1 | grep -E 'NoClassDefFound|Started' | head -1
INFO ... : Started BootApplication in 0.914 seconds

--   클래스 조건이 막아 줘서 안 읽혔다
--   6.3절에서 본 그 이득이다


-- 그런데 조건을 메서드에만 붙이면

@AutoConfiguration
public class PrettyAutoConfiguration {
    @Bean
    @ConditionalOnClass(name = "com.fasterxml.jackson.databind.ObjectMapper")
    public ObjectMapper prettyMapper() { return new ObjectMapper(); }
}

$ ./gradlew bootRun 2>&1 | head -3
Exception in thread "main" java.lang.IllegalStateException:
  Failed to introspect annotated methods
Caused by: java.lang.NoClassDefFoundError:
  com/fasterxml/jackson/databind/ObjectMapper

--   메서드를 읽으려면 반환 타입을 로딩해야 한다
--   그래서 부트는 안쪽 클래스로 감싼다


-- 부트가 감싸는 방식

@AutoConfiguration
public class PrettyAutoConfiguration {
    @Configuration(proxyBeanMethods = false)
    @ConditionalOnClass(name = "com.fasterxml.jackson.databind.ObjectMapper")
    static class JacksonPresent {
        @Bean public ObjectMapper prettyMapper() { return new ObjectMapper(); }
    }
}

$ ./gradlew bootRun 2>&1 | grep -c 'Started BootApplication'
1
$ curl -s -o /dev/null -w '%{http_code}\n' localhost:8080/hello
200

$ unzip -p "$AC" \
    'org/springframework/boot/autoconfigure/jackson/JacksonAutoConfiguration*.class' \
  > /dev/null; unzip -l "$AC" | grep -c 'JacksonAutoConfiguration\$'
       5

--   부트 것도 안쪽 클래스가 다섯이다


-- 여러 개면 전부 있어야 한다

@ConditionalOnClass(name = {
    "com.fasterxml.jackson.databind.ObjectMapper",
    "org.apache.commons.csv.CSVFormat"
})

$ ./gradlew bootRun --args='--debug' 2>&1 \
    | grep -A3 'PrettyAutoConfiguration' | head -4
   PrettyAutoConfiguration:
      Did not match:
         - @ConditionalOnClass did not find required class
           'org.apache.commons.csv.CSVFormat'

--   못 찾은 것만 이름이 나온다


-- 없을 때 쪽

@AutoConfiguration
public class StorageAutoConfiguration {
    @Configuration(proxyBeanMethods = false)
    @ConditionalOnClass(name = "org.apache.commons.csv.CSVFormat")
    static class WithCsv {
        @Bean public String writer() { return "CSV 로 쓴다"; }
    }

    @Configuration(proxyBeanMethods = false)
    @ConditionalOnMissingClass("org.apache.commons.csv.CSVFormat")
    static class WithoutCsv {
        @Bean public String writer() { return "그냥 쉼표로 쓴다"; }
    }
}

$ curl -s 'localhost:8080/beans/one?name=writer'
그냥 쉼표로 쓴다

// 라이브러리를 넣으면
implementation 'org.apache.commons:commons-csv:1.11.0'

$ curl -s 'localhost:8080/beans/one?name=writer'
CSV 로 쓴다

$ ./gradlew bootRun --args='--debug' 2>&1 \
    | grep -A2 'WithoutCsv' | head -3
   StorageAutoConfiguration$WithoutCsv:
      Did not match:
         - @ConditionalOnMissingClass found unwanted class
           'org.apache.commons.csv.CSVFormat'

--   한 줄을 넣었더니 구현이 갈렸다
--   5.3절의 그 한 줄이 이런 일을 한다


-- 버전은 안 본다

ext['jackson-bom.version'] = '2.9.10'

$ ./gradlew bootRun --args='--debug' 2>&1 \
    | grep -c 'PrettyAutoConfiguration matched'
1

$ curl -s -o /dev/null -w '%{http_code}\n' localhost:8080/json
500

--   조건은 맞았는데 부를 때 터진다
--   5.1절의 셋째 시점이다


